using System;using System.IO;using System.Text;using System.Collections;using System.Collections.Generic;using System.Globalization;using Nwc.XmlRpc;
static class Host {
 static Dictionary<object,int> ids;static string trace;static int logMode,events,action;static bool nested;
 public static string H(string s){if(s==null)return "-";if(s.Length==0)return ".";string o="";foreach(char c in s)o+=((int)c&255).ToString("x2")+((int)c>>8).ToString("x2");return o;}
 static string D(string h){if(h=="-")return null;if(h==".")return "";var b=Convert.FromHexString(h);string o="";for(int i=0;i<b.Length;i+=2)o+=(char)(b[i]|b[i+1]<<8);return o;}
 static string Dump(object value){if(value==null)return "N";if(value is string s)return "S:"+H(s);if(value is int i)return "I:"+i;if(value is bool b)return b?"T":"F";if(value is double d)return "R:"+BitConverter.DoubleToInt64Bits(d).ToString("x16");if(value is DateTime date)return "D:"+date.Ticks+":"+(int)date.Kind;
  if(ids.TryGetValue(value,out int prior))return "@"+prior;int id=ids.Count+1;ids.Add(value,id);
  if(value is byte[] bytes)return "B:"+id+":"+Convert.ToHexString(bytes).ToLowerInvariant();
  if(value is ArrayList array){var values=new List<string>();foreach(var x in array)values.Add(Dump(x));return "A:"+id+"["+string.Join(',',values)+"]";}
  if(value is Hashtable map){var keys=new List<string>();foreach(string k in map.Keys)keys.Add(k);keys.Sort(StringComparer.Ordinal);var values=new List<string>();foreach(string k in keys)values.Add(H(k)+"="+Dump(map[k]));return "M:"+id+"{"+string.Join(',',values)+"}";}
  return "X:"+value.GetType().FullName;
 }
 static string Run(XmlRpcResponseDeserializer parser,string xml){string result="";try{var response=(XmlRpcResponse)parser.Deserialize(xml);result="OK:"+(response.IsFault?1:0)+":"+Dump(response.Value);if((action&1)!=0)result+=";C:"+response.FaultCode;if((action&2)!=0)result+=";S:"+H(response.FaultString);}catch(Exception e){result+=";E:"+e.GetType().FullName+":"+H(e.Message);}return result;}

 class TextInput:TextReader {readonly string data;readonly int chunk,fail;readonly bool closeFail;readonly List<string> calls;int position,reads;public TextInput(string data,int chunk,int fail,bool closeFail,List<string> calls){this.data=data;this.chunk=chunk;this.fail=fail;this.closeFail=closeFail;this.calls=calls;}public override int Read(char[] buffer,int index,int count){calls.Add("R:"+count);if(++reads==fail)throw new Exception("read");int n=Math.Min(count,Math.Min(chunk,data.Length-position));data.CopyTo(position,buffer,index,n);position+=n;return n;}protected override void Dispose(bool disposing){calls.Add("X");if(closeFail)throw new Exception("close");base.Dispose(disposing);}}
 class BytesInput:Stream {readonly byte[] data;readonly int chunk,fail;readonly bool closeFail,readable;readonly List<string> calls;int position,reads;public BytesInput(byte[] data,int chunk,int fail,bool closeFail,bool readable,List<string> calls){this.data=data;this.chunk=chunk;this.fail=fail;this.closeFail=closeFail;this.readable=readable;this.calls=calls;}public override bool CanRead{get{calls.Add("C");return readable;}}public override bool CanSeek=>false;public override bool CanWrite=>false;public override long Length=>throw new NotSupportedException();public override long Position{get=>position;set=>throw new NotSupportedException();}public override int Read(byte[] buffer,int index,int count){calls.Add("R:"+count);if(++reads==fail)throw new Exception("read");int n=Math.Min(count,Math.Min(chunk,data.Length-position));Array.Copy(data,position,buffer,index,n);position+=n;return n;}protected override void Dispose(bool disposing){calls.Add("X");if(closeFail)throw new Exception("close");base.Dispose(disposing);}public override void Flush()=>throw new NotSupportedException();public override long Seek(long offset,SeekOrigin origin)=>throw new NotSupportedException();public override void SetLength(long value)=>throw new NotSupportedException();public override void Write(byte[] buffer,int index,int count)=>throw new NotSupportedException();}
 static void StreamCase(string line){var a=line.Split(' ');int mode=int.Parse(a[1]),chunk=int.Parse(a[2]),fail=int.Parse(a[3]),flags=int.Parse(a[5]);action=0;bool closeFail=a[4]=="1";ids=new Dictionary<object,int>(ReferenceEqualityComparer.Instance);trace="";var calls=new List<string>();var parser=new XmlRpcResponseDeserializer();Logger.Delegate=(flags&8)!=0?(message,level)=>calls.Add("L:"+H(message)):null;TextReader input=null;string result="",extra="-";try{if((flags&1)==0){if(mode==0)input=new TextInput(D(a[6]),chunk,fail,closeFail,calls);else input=new StreamReader((flags&2)!=0?null:new BytesInput(a[6]=="."?Array.Empty<byte>():Convert.FromHexString(a[6]),chunk,fail,closeFail,(flags&16)==0,calls));}var r=(XmlRpcResponse)parser.Deserialize(input);result="OK:"+(r.IsFault?1:0)+":"+Dump(r.Value)+";C:"+r.FaultCode+";S:"+H(r.FaultString);}catch(Exception e){result+=";E:"+e.GetType().FullName+":"+H(e.Message);}if((flags&4)!=0&&input!=null){try{input.Close();}catch(Exception e){extra="E:"+e.GetType().FullName+":"+H(e.Message);}}string second=Run(parser,"<root/>");Console.WriteLine(result+"|"+extra+"|"+second+"|"+string.Join(';',calls));Logger.Delegate=null;}
 public static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){if(line.StartsWith("S ")){StreamCase(line);continue;}var a=line.Split(' ');logMode=int.Parse(a[0]);action=int.Parse(a[1]);trace="";events=0;nested=false;ids=new Dictionary<object,int>(ReferenceEqualityComparer.Instance);var parser=new XmlRpcResponseDeserializer();Logger.Delegate=logMode==0?null:(message,level)=>{trace+=H(message)+";";events++;if(logMode>0&&events==logMode)throw new Exception("logger");if(logMode<=-2&&!nested&&(logMode==-2||events==-logMode)){nested=true;trace+="nested:"+Run(parser,"<methodResponse><params><param><value><int>7</int></value></param></params></methodResponse>")+";";}};string first=Run(parser,D(a[2]));string second=Run(parser,D(a[3]));Console.WriteLine(first+"|"+second+"|"+trace);Logger.Delegate=null;}}
}
